from astropy.utils import _compiler
import numpy as np
import astropy.units as u


# A simple duck array that doesn't have a unit attribute
class SimpleDuckArray:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f'SimpleDuckArray({self.value})'

    def __array_ufunc__(self, function, method, *inputs, **kwargs):
        # Just convert everything to numpy arrays and call the ufunc
        new_inputs = []
        for inp in inputs:
            if isinstance(inp, SimpleDuckArray):
                new_inputs.append(inp.value)
            else:
                new_inputs.append(inp)
        result = function(*new_inputs, **kwargs)
        return SimpleDuckArray(result)

    def __radd__(self, other):
        return SimpleDuckArray(other + self.value)

    def __add__(self, other):
        return SimpleDuckArray(other + self.value)

# Test with a simple duck array
print('Test: (1 * u.m) + SimpleDuckArray(2)')
try:
    result = (1 * u.m) + SimpleDuckArray(2)
    print(f'  Result: {result}')
except Exception as e:
    print(f'  Error: {type(e).__name__}: {e}')
"

